CREATE TABLE schema_migrations(version VARCHAR(64) PRIMARY KEY,applied_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('member','moderator','admin') NOT NULL DEFAULT 'member',points BIGINT NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'active',locale VARCHAR(10) NOT NULL DEFAULT 'zh-CN',avatar_path VARCHAR(255) NULL,created_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expires_at DATETIME(6) NOT NULL,last_seen_at DATETIME(6) NOT NULL,user_agent_hash CHAR(64) NOT NULL,ip_prefix_hash CHAR(64) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),KEY ix_sessions_user_expiry(user_id,expires_at),KEY ix_sessions_expires(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(100) NOT NULL UNIQUE,title VARCHAR(100) NOT NULL,description VARCHAR(500) NOT NULL DEFAULT '',position INT NOT NULL DEFAULT 0,is_visible TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE topics(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,slug VARCHAR(160) NOT NULL,title VARCHAR(120) NOT NULL,reply_count INT UNSIGNED NOT NULL DEFAULT 0,view_count BIGINT UNSIGNED NOT NULL DEFAULT 0,is_pinned TINYINT(1) NOT NULL DEFAULT 0,is_locked TINYINT(1) NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'normal',created_at DATETIME(6) NOT NULL,last_post_at DATETIME(6) NOT NULL,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(user_id) REFERENCES users(id),KEY ix_topics_category_activity(category_id,status,is_pinned,last_post_at,id),KEY ix_topics_activity(status,is_pinned,last_post_at,id),KEY ix_topics_user_last_post(user_id,last_post_at,id),KEY ix_topics_user_created(user_id,created_at,id),FULLTEXT KEY ft_topics_title(title)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE posts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,topic_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body_markdown MEDIUMTEXT NOT NULL,body_html MEDIUMTEXT NOT NULL,revision INT NOT NULL DEFAULT 1,status VARCHAR(16) NOT NULL DEFAULT 'normal',created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NULL,FOREIGN KEY(topic_id) REFERENCES topics(id),FOREIGN KEY(user_id) REFERENCES users(id),KEY ix_posts_topic_created(topic_id,status,created_at,id),KEY ix_posts_topic_order(topic_id,status,id),KEY ix_posts_user_created(user_id,created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE post_revisions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,post_id BIGINT UNSIGNED NOT NULL,editor_id BIGINT UNSIGNED NOT NULL,body_markdown MEDIUMTEXT NOT NULL,reason VARCHAR(255) NOT NULL DEFAULT '',created_at DATETIME(6) NOT NULL,FOREIGN KEY(post_id) REFERENCES posts(id),FOREIGN KEY(editor_id) REFERENCES users(id),KEY ix_post_revisions_post(post_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE point_ledger(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,delta INT NOT NULL,reason VARCHAR(120) NOT NULL,ref_type VARCHAR(24) NOT NULL,ref_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(100) NOT NULL UNIQUE,created_at DATETIME(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),KEY ix_ledger_user_created(user_id,created_at,id),KEY ix_point_ledger_ref(ref_type,ref_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE settings(setting_key VARCHAR(64) PRIMARY KEY,setting_value TEXT NOT NULL,updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE plugins(name VARCHAR(32) PRIMARY KEY,version VARCHAR(32) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,config_json JSON NOT NULL,installed_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE themes(name VARCHAR(64) PRIMARY KEY,version VARCHAR(32) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 0,config_json JSON NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED NULL,action VARCHAR(64) NOT NULL,target_type VARCHAR(32) NOT NULL,target_id BIGINT UNSIGNED NULL,metadata_json JSON NOT NULL,ip_prefix_hash CHAR(64) NOT NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL,KEY ix_audit_created(created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE rate_limits(bucket CHAR(64) PRIMARY KEY,counter INT UNSIGNED NOT NULL,reset_at DATETIME(6) NOT NULL,KEY ix_rate_limits_expiry(reset_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE market_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,kind ENUM('plugin','theme') NOT NULL,package_name VARCHAR(32) NOT NULL,title VARCHAR(100) NOT NULL,version VARCHAR(32) NOT NULL,summary VARCHAR(500) NOT NULL,package_file VARCHAR(64) NOT NULL,sha256 CHAR(64) NOT NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',review_note VARCHAR(500) NOT NULL DEFAULT '',created_at DATETIME(6) NOT NULL,reviewed_at DATETIME(6) NULL,FOREIGN KEY(user_id) REFERENCES users(id),KEY ix_market_status(status,created_at,id),KEY ix_market_submissions_user_id(user_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
